package com.zjnu.lab.security;
import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.http.HttpStatus; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.factory.PasswordEncoderFactories; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.HttpStatusEntryPoint; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration @EnableMethodSecurity @RequiredArgsConstructor public class SecurityConfig {
 private final JwtFilter filter;
 @Bean PasswordEncoder passwordEncoder(){return PasswordEncoderFactories.createDelegatingPasswordEncoder();}
 @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint(new HttpStatusEntryPoint(HttpStatus.UNAUTHORIZED)).accessDeniedHandler((request,response,error)->response.setStatus(HttpStatus.FORBIDDEN.value()))).authorizeHttpRequests(a->a.requestMatchers("/auth/login","/swagger-ui/**","/v3/api-docs/**","/h2-console/**").permitAll().requestMatchers("/dashboard").hasAnyRole("LAB_ADMIN","SYSTEM_ADMIN").requestMatchers("/ai/ask").hasRole("USER").requestMatchers("/manage/reservations","/manage/reservations/**").hasRole("LAB_ADMIN").requestMatchers("/reservations/**").hasAnyRole("USER","LAB_ADMIN").requestMatchers(HttpMethod.GET,"/labs/**","/devices/**").authenticated().requestMatchers("/admin/**").hasRole("SYSTEM_ADMIN").requestMatchers("/manage/**").hasAnyRole("LAB_ADMIN","SYSTEM_ADMIN").anyRequest().authenticated()).headers(x->x.frameOptions(f->f.sameOrigin())).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}
}
